3	function mean(xs) {
4	  if (!xs.length) return NaN;
5	  return xs.reduce((a, b) => a + b, 0) / xs.length;
6	}
7	
8	// Middle value of the numbers.
9	function median(xs) {
10	  if (!xs.length) return NaN;
11	  xs.sort((a, b) => a - b);
12	  return xs[Math.floor(xs.length / 2)];
13	}
14	
15	// Most frequent value (the smallest one when several are tied).
16	function mode(xs) {
17	  const counts = new Map();
18	  for (const x of xs) counts.set(x, (counts.get(x) || 0) + 1);
19	  let best = NaN, bestN = 0;
20	  for (const [x, n] of counts) if (n > bestN || (n === bestN && x < best)) { best = x; bestN = n; }
21	  return best;
22	}
23	
24	module.exports = { mean, median, mode };
